function probe(params) {
  return Math.pow(1 + params.x, params.n);
}

function draw(ctx, state) {
  const p = state.params;
  const w = state.w, h = state.h;
  const ink = state.dark ? '#c9d1db' : '#3a4350';
  const blue = '#4f8cff', gray = '#9aa4b2';
  const L = 16, R = w - 16, T = 42, B = h - 16;
  const pw = Math.max(1, R - L), ph = Math.max(1, B - T);
  const ymax = Math.pow(3, p.n);
  const X = x => L + pw * x / 2;
  const Y = y => B - ph * y / ymax;
  const exact = x => Math.pow(1 + x, p.n);
  const linear = x => 1 + p.n * x;

  ctx.clearRect(0, 0, w, h);
  ctx.lineWidth = 1;
  ctx.strokeStyle = ink;
  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.moveTo(L, T);
  ctx.lineTo(L, B);
  ctx.lineTo(R, B);
  ctx.stroke();

  ctx.font = '12px system-ui';
  ctx.fillStyle = blue;
  ctx.fillText('Exact', L, 28);
  ctx.fillStyle = gray;
  ctx.fillText('Linear', L + 52, 28);

  ctx.strokeStyle = gray;
  ctx.lineWidth = 2;
  ctx.setLineDash([6, 5]);
  ctx.beginPath();
  ctx.moveTo(X(0), Y(linear(0)));
  ctx.lineTo(X(2), Y(linear(2)));
  ctx.stroke();

  ctx.strokeStyle = blue;
  ctx.setLineDash([]);
  ctx.beginPath();
  for (let i = 0; i <= 100; i++) {
    const x = 2 * i / 100;
    if (i === 0) ctx.moveTo(X(x), Y(exact(x)));
    else ctx.lineTo(X(x), Y(exact(x)));
  }
  ctx.stroke();

  const x = Math.max(0.0001, Math.min(2, p.x));
  ctx.globalAlpha = 0.25;
  ctx.strokeStyle = ink;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(X(x), B);
  ctx.lineTo(X(x), Y(exact(x)));
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.fillStyle = gray;
  ctx.beginPath();
  ctx.arc(X(x), Y(linear(x)), 3.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(X(x), Y(exact(x)), 4, 0, Math.PI * 2);
  ctx.fill();

  const xt = 1 + Math.sin(state.t * 0.8);
  ctx.strokeStyle = blue;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(X(xt), Y(exact(xt)), 5, 0, Math.PI * 2);
  ctx.stroke();
}

