function probe(params) {
  const b = params.beta;
  const s = Math.sqrt(1 - b * b);
  return b * b / (s * (1 + s));
}

function draw(ctx, state) {
  const w = state.w, h = state.h;
  const beta = state.params.beta;
  const ink = state.dark ? '#c9d1db' : '#3a4350';
  const blue = '#4f8cff', grey = '#9aa4b2';
  const x0 = 22, x1 = w - 16, y0 = h - 24, yt = 18;
  const maxE = probe({beta: 0.99});
  const X = b => x0 + (x1 - x0) * b / 0.99;
  const Y = e => y0 - (y0 - yt) * Math.log1p(e) / Math.log1p(maxE);
  const classical = b => 0.5 * b * b;

  ctx.clearRect(0, 0, w, h);
  ctx.lineWidth = 1;
  ctx.strokeStyle = ink;
  ctx.globalAlpha = 0.45;
  ctx.beginPath();
  ctx.moveTo(x0, yt);
  ctx.lineTo(x0, y0);
  ctx.lineTo(x1, y0);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.font = '12px system-ui';
  ctx.textAlign = 'left';
  ctx.fillStyle = blue;
  ctx.fillText('real', x0 + 6, yt + 12);
  ctx.fillStyle = grey;
  ctx.fillText('½mv²', x0 + 6, yt + 29);

  ctx.strokeStyle = grey;
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  for (let i = 0; i <= 100; i++) {
    const b = 0.99 * i / 100;
    const x = X(b), y = Y(classical(b));
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.strokeStyle = blue;
  ctx.beginPath();
  for (let i = 0; i <= 140; i++) {
    const b = 0.99 * i / 140;
    const x = X(b), y = Y(probe({beta: b}));
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();

  const px = X(beta);
  ctx.globalAlpha = 0.22;
  ctx.strokeStyle = ink;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(px, y0);
  ctx.lineTo(px, yt);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.fillStyle = grey;
  ctx.beginPath();
  ctx.arc(px, Y(classical(beta)), 4, 0, 2 * Math.PI);
  ctx.fill();
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(px, Y(probe({beta: beta})), 5, 0, 2 * Math.PI);
  ctx.fill();

  const travel = beta * (0.5 - 0.5 * Math.cos(state.t * 1.5));
  ctx.globalAlpha = 0.75;
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(X(travel), Y(probe({beta: travel})), 2.5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.globalAlpha = 1;
}

function probe(params) {
  var A = Math.abs(params.amplitude_m);
  var m = params.m_kg;
  var k = params.k_Nm;
  var k3 = params.k3_Nm3 || 0;
  var x = A, v = 0, t = 0;
  var dt = Math.sqrt(m / k) / 500;
  var first = null;
  function acc(xx) { return -(k * xx + k3 * xx * xx * xx) / m; }
  for (var i = 0; i < 200000; i++) {
    var ox = x;
    var a1 = acc(x);
    var k1x = v, k1v = a1;
    var k2x = v + 0.5 * dt * k1v;
    var k2v = acc(x + 0.5 * dt * k1x);
    var k3x = v + 0.5 * dt * k2v;
    var k3v = acc(x + 0.5 * dt * k2x);
    var k4x = v + dt * k3v;
    var k4v = acc(x + dt * k3x);
    x += dt * (k1x + 2 * k2x + 2 * k3x + k4x) / 6;
    v += dt * (k1v + 2 * k2v + 2 * k3v + k4v) / 6;
    t += dt;
    if (ox < 0 && x >= 0 && v > 0) {
      var cross = t - dt + dt * (-ox) / (x - ox);
      if (first === null) first = cross;
      else return cross - first;
    }
  }
  return NaN;
}

function springPath(ctx, x0, x1, y, coils) {
  ctx.beginPath();
  ctx.moveTo(x0, y);
  var lead = Math.min(12, (x1 - x0) * 0.12);
  ctx.lineTo(x0 + lead, y);
  var start = x0 + lead, end = x1 - lead;
  var n = coils * 2;
  for (var i = 1; i < n; i++) {
    var xx = start + (end - start) * i / n;
    ctx.lineTo(xx, y + (i % 2 ? -8 : 8));
  }
  ctx.lineTo(end, y);
  ctx.lineTo(x1, y);
  ctx.stroke();
}

function draw(ctx, state) {
  var p = state.params, w = state.w, h = state.h;
  var ink = state.dark ? '#c9d1db' : '#3a4350';
  var cy = h * 0.56;
  var wallX = 24;
  var r = Math.max(10, Math.min(18, w * 0.045));
  var eq = w * 0.54;
  var ampMax = Math.max(8, Math.min(w * 0.31, eq - wallX - r - 12, w - 16 - r - eq));
  var amp = ampMax * Math.min(1, Math.abs(p.amplitude_m));
  var omega = Math.sqrt(p.k_Nm / p.m_kg);
  var x = eq + amp * Math.cos(omega * state.t);
  var wallHalf = Math.max(12, Math.min(46, cy - 16, h - cy - 16));

  ctx.lineWidth = 1;
  ctx.strokeStyle = ink;
  ctx.fillStyle = ink;
  ctx.font = '12px system-ui';
  ctx.textAlign = 'left';
  ctx.fillText('equilibrium', Math.min(eq + 6, w - 82), 27);

  ctx.save();
  ctx.setLineDash([3, 5]);
  ctx.globalAlpha = 0.45;
  ctx.beginPath();
  ctx.moveTo(eq, 36);
  ctx.lineTo(eq, h - 16);
  ctx.stroke();
  ctx.restore();

  ctx.beginPath();
  ctx.moveTo(wallX, cy - wallHalf);
  ctx.lineTo(wallX, cy + wallHalf);
  ctx.stroke();
  for (var j = -2; j <= 2; j++) {
    var yy = cy + j * wallHalf / 3;
    ctx.beginPath();
    ctx.moveTo(wallX, yy);
    ctx.lineTo(16, yy + 6);
    ctx.stroke();
  }

  ctx.save();
  ctx.strokeStyle = '#9aa4b2';
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);
  springPath(ctx, wallX, x - r, cy, 8);
  ctx.beginPath();
  ctx.arc(x, cy, r, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();

  ctx.strokeStyle = '#4f8cff';
  ctx.lineWidth = 2;
  springPath(ctx, wallX, x - r, cy, 8);
  ctx.fillStyle = '#4f8cff';
  ctx.beginPath();
  ctx.arc(x, cy, r, 0, Math.PI * 2);
  ctx.fill();
}

function probe(params) {
  var m = params.m_kg, k = params.k_Nm, A = params.amplitude_m;
  var k3 = params.k3_Nm3 || 0, T = Math.max(0, params.t_s);
  var x = A, v = 0;
  if (T === 0) return 0.5 * k * A * A;
  var n = Math.max(1, Math.ceil(T / 0.002));
  var dt = T / n;
  function acceleration(q) { return -(k * q + k3 * q * q * q) / m; }
  var a = acceleration(x);
  for (var i = 0; i < n; i++) {
    v += 0.5 * a * dt;
    x += v * dt;
    a = acceleration(x);
    v += 0.5 * a * dt;
  }
  return 0.5 * m * v * v + 0.5 * k * x * x;
}

function draw(ctx, state) {
  var p = state.params, w = state.w, h = state.h;
  var ink = state.dark ? '#c9d1db' : '#3a4350';
  var blue = '#4f8cff', gray = '#9aa4b2';
  ctx.clearRect(0, 0, w, h);
  ctx.lineWidth = 1;
  ctx.font = '12px system-ui';

  var omega = Math.sqrt(p.k_Nm / p.m_kg);
  var phase = omega * (p.t_s + state.t);
  var c = Math.cos(phase), s = Math.sin(phase);
  var mw = Math.min(36, Math.max(26, w * 0.1)), mh = 32;
  var mid = (70 + w - 16) / 2;
  var travel = Math.max(0, Math.min(85, (w - 86) / 2 - mw / 2 - 3));
  var cx = mid + travel * c;
  var cy = Math.max(60, Math.min(h * 0.42, h - 90));
  var leftEdge = cx - mw / 2;

  ctx.strokeStyle = ink;
  ctx.beginPath();
  ctx.moveTo(16, cy - 40); ctx.lineTo(16, cy + 40);
  ctx.moveTo(22, cy + 28); ctx.lineTo(w - 16, cy + 28);
  ctx.stroke();

  function springPath() {
    ctx.beginPath();
    ctx.moveTo(18, cy);
    var end = leftEdge, coils = 10;
    for (var i = 1; i < coils; i++) {
      var xx = 18 + (end - 18) * i / coils;
      ctx.lineTo(xx, cy + (i % 2 ? -7 : 7));
    }
    ctx.lineTo(end, cy);
  }

  ctx.strokeStyle = gray;
  ctx.setLineDash([5, 4]);
  springPath(); ctx.stroke();
  ctx.strokeRect(leftEdge, cy - mh / 2, mw, mh);
  ctx.setLineDash([]);

  ctx.strokeStyle = blue;
  springPath(); ctx.stroke();
  ctx.fillStyle = blue;
  ctx.fillRect(leftEdge, cy - mh / 2, mw, mh);

  var barX = 16, barW = w - 32, barY = h - 28, barH = 12;
  var kinetic = s * s, potential = c * c;
  ctx.fillStyle = blue;
  ctx.fillRect(barX, barY, barW * kinetic, barH);
  ctx.globalAlpha = 0.35;
  ctx.fillRect(barX + barW * kinetic, barY, barW * potential, barH);
  ctx.globalAlpha = 1;
  ctx.strokeStyle = gray;
  ctx.setLineDash([5, 4]);
  ctx.strokeRect(barX, barY, barW, barH);
  ctx.setLineDash([]);
  ctx.fillStyle = ink;
  ctx.textAlign = 'left';
  ctx.fillText('Energy', barX, barY - 10);
}

