function draw(ctx, state) {
  var w = state.w, h = state.h, ink = state.dark ? '#c9d1db' : '#3a4350';
  var left = 36, right = w - 20, top = 42, bottom = h - 40;
  var x = Math.max(0.1, Math.min(89, state.params.x));
  var xmax = Math.PI / 2, ymax = xmax * 1.06;
  function px(a) { return left + (a / xmax) * (right - left); }
  function py(v) { return bottom - (v / ymax) * (bottom - top); }

  ctx.save();
  ctx.lineWidth = 1;
  ctx.strokeStyle = ink;
  ctx.globalAlpha = 0.45;
  ctx.beginPath();
  ctx.moveTo(left, top);
  ctx.lineTo(left, bottom);
  ctx.lineTo(right, bottom);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.font = '12px system-ui';
  ctx.textAlign = 'left';
  ctx.fillStyle = '#4f8cff';
  ctx.fillText('sin x', left, 22);
  ctx.fillStyle = '#9aa4b2';
  ctx.fillText('x', left + 48, 22);
  ctx.fillStyle = ink;
  ctx.textAlign = 'right';
  ctx.fillText('angle', right, bottom + 20);

  var a = x * Math.PI / 180;
  ctx.strokeStyle = '#9aa4b2';
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  ctx.moveTo(px(0), py(0));
  ctx.lineTo(px(a), py(a));
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.strokeStyle = '#4f8cff';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  var n = Math.max(2, Math.ceil(x));
  for (var i = 0; i <= n; i++) {
    var ai = a * i / n;
    if (i === 0) ctx.moveTo(px(ai), py(Math.sin(ai)));
    else ctx.lineTo(px(ai), py(Math.sin(ai)));
  }
  ctx.stroke();

  var u = (1 - Math.cos(state.t * 0.9)) / 2;
  var at = a * u;
  ctx.fillStyle = '#9aa4b2';
  ctx.beginPath();
  ctx.arc(px(at), py(at), 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#4f8cff';
  ctx.beginPath();
  ctx.arc(px(at), py(Math.sin(at)), 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function probe(params) {
  const g = 9.81;
  const a0 = params.amplitude_deg * Math.PI / 180;
  let a = 1, b = Math.cos(a0 / 2);
  for (let i = 0; i < 20 && Math.abs(a - b) > 1e-15; i++) {
    const nextA = (a + b) / 2;
    b = Math.sqrt(a * b);
    a = nextA;
  }
  const K = Math.PI / (2 * a);
  return 4 * Math.sqrt(params.L_m / g) * K;
}

function draw(ctx, state) {
  const p = state.params, w = state.w, h = state.h;
  const ink = state.dark ? '#c9d1db' : '#3a4350';
  const blue = '#4f8cff', grey = '#9aa4b2';
  const amp = p.amplitude_deg * Math.PI / 180;
  const x = w / 2, y = 32;
  const radius = Math.max(4, Math.min(8, w / 60));
  const rod = Math.max(20, Math.min(h - y - 16 - radius, w * 0.55));
  const displayScale = 5;
  const realPeriod = probe(p);
  const rulePeriod = 2 * Math.PI * Math.sqrt(p.L_m / 9.81);
  const realPhase = 2 * Math.PI * state.t / realPeriod;
  const rulePhase = 2 * Math.PI * state.t / rulePeriod;
  const realAngle = displayScale * (amp * Math.sin(realPhase) + amp * amp * amp * Math.sin(3 * realPhase) / 192);
  const ruleAngle = displayScale * amp * Math.sin(rulePhase);

  ctx.save();
  ctx.lineWidth = 1;
  ctx.strokeStyle = ink;
  ctx.beginPath();
  ctx.moveTo(x - 28, y);
  ctx.lineTo(x + 28, y);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(x, y, 2, 0, 2 * Math.PI);
  ctx.fillStyle = ink;
  ctx.fill();

  function pendulum(angle, color, dashed, fill) {
    const bx = x + rod * Math.sin(angle);
    const by = y + rod * Math.cos(angle);
    ctx.strokeStyle = color;
    ctx.setLineDash(dashed ? [5, 5] : []);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(bx, by);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.beginPath();
    ctx.arc(bx, by, radius, 0, 2 * Math.PI);
    if (fill) {
      ctx.fillStyle = color;
      ctx.fill();
    } else {
      ctx.stroke();
    }
  }

  pendulum(ruleAngle, grey, true, false);
  pendulum(realAngle, blue, false, true);

  ctx.font = '12px system-ui';
  ctx.fillStyle = ink;
  ctx.textBaseline = 'bottom';
  ctx.textAlign = 'left';
  ctx.fillText('Real', 16, h - 16);
  ctx.textAlign = 'right';
  ctx.fillText('Rule', w - 16, h - 16);
  ctx.restore();
}

function probe(params){
  const a=params.amplitude_deg*Math.PI/180;
  const k=Math.sin(a/2);
  let x=1,y=Math.sqrt(1-k*k);
  for(let i=0;i<12&&Math.abs(x-y)>1e-15;i++){
    const n=(x+y)/2;
    y=Math.sqrt(x*y);
    x=n;
  }
  return 2*Math.PI*Math.sqrt(params.L_m/9.81)/x;
